#: scripts/luca_v2/luca_character.py · sha256:b2cec1f7ded33c13
LUCA_CHARACTER_PY = '"""\nThe character, described in exactly one place.\n\nTwo rules are encoded here rather than trusted to discipline:\n\n  * No celebrity name ever enters a prompt. Naming a real actor does not just\n    invite likeness problems, it *ages the character* — the model reproduces the\n    person it has seen in the training data, which is a 50-something. He is\n    described by attributes only, and the trigger word `ohwx` carries the\n    identity once the LoRA is trained.\n  * Hands are never near the face, and framing is explicit. Face/hand contact\n    is where diffusion models produce the artefacts that make a carousel look\n    synthetic.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Dict, List\n\n#: The LoRA trigger word. Rare by construction, so it cannot collide with a real\n#: token, and stable across the dataset, training and inference.\nTRIGGER = "ohwx"\n\n#: The age the character is, and stays. Everything downstream is anchored to it.\nAGE = 27\n\n#: The canonical description. Used verbatim for the master and the dataset, and\n#: as the prefix for every carousel image, so identity language never drifts.\nSUBJECT = (\n    f"{TRIGGER} 27-year-old Italian man, athletic build, sun-kissed dirty blonde "\n    "tousled hair, piercing blue-green eyes, sharp jawline, light 3-day stubble"\n)\n\n#: Qualities that make an image read as a real photograph rather than a render.\nPHOTO_REALISM = (\n    "candid 24mm iPhone 16 Pro photo, natural sunlight, skin pores, "\n    "unretouched, photorealistic, sharp focus on the eyes"\n)\n\n#: Never rendered. Negative prompt only.\nNEGATIVE_PROMPT = (\n    "cartoon, illustration, 3d render, cgi, painting, anime, "\n    "airbrushed skin, plastic skin, waxy skin, doll-like, "\n    "deformed hands, extra fingers, fused fingers, missing fingers, "\n    "hands near face, hand covering face, face touching, "\n    "mutated, distorted, disfigured, bad anatomy, bad proportions, "\n    "extra limbs, long neck, asymmetric eyes, crossed eyes, "\n    "oversaturated, hdr, oversharpened, watermark, text, logo, signature, "\n    "blurry, low resolution, jpeg artifacts, grainy, "\n    "old, elderly, aged, wrinkles, grey hair, balding, "\n    "car door clipping, cropped head, out of frame"\n)\n\n#: A copyright-safe note for the metrics: what we deliberately do not say.\nFORBIDDEN_TERMS = ("brad pitt", "brad", "pitt", "bradley")\n\n\ndef check_prompt(text: str) -> str:\n    """Raise if a forbidden name leaked into a prompt. Called before generating."""\n    lowered = text.lower()\n    for term in FORBIDDEN_TERMS:\n        if term in lowered:\n            raise ValueError(f"forbidden name {term!r} in prompt: {text[:120]!r}")\n    return text\n\n\n# --------------------------------------------------------------------------- #\n# Dataset — 15 varied photographs of the same person\n# --------------------------------------------------------------------------- #\n#: (name, prompt, seed). Variety is the point: if all fifteen are close-ups he\n#: learns one crop, and the carousel inherits that framing.\n#:\n#: `framing` is spelled out per image — "close-up", "medium shot", "full body" —\n#: because that is what the LoRA actually learns about composition, and what\n#: keeps a subject from being clipped by a car door later.\nDATASET: List[Dict[str, object]] = [\n    {"name": "train_01_front_closeup",\n     "framing": "close-up portrait, facing camera",\n     "lighting": "soft window light from the left",\n     "expression": "relaxed neutral expression", "seed": 1001},\n    {"name": "train_02_three_quarter",\n     "framing": "head and shoulders, three-quarter view turned to his right",\n     "lighting": "warm late-afternoon sun, slight rim light",\n     "expression": "subtle closed-mouth smile", "seed": 1002},\n    {"name": "train_03_profile",\n     "framing": "head and shoulders, near-profile looking off to the left",\n     "lighting": "hard directional sunlight from the right",\n     "expression": "serious, jaw set", "seed": 1003},\n    {"name": "train_04_medium_smile",\n     "framing": "medium shot from the chest up, facing camera",\n     "lighting": "bright open shade",\n     "expression": "genuine wide smile showing teeth", "seed": 1004},\n    {"name": "train_05_medium_street",\n     "framing": "medium shot, walking toward camera",\n     "lighting": "overcast diffused daylight",\n     "expression": "laughing, looking slightly off camera", "seed": 1005},\n    {"name": "train_06_full_body",\n     "framing": "full body shot, standing, entire figure in frame",\n     "lighting": "golden hour backlight",\n     "expression": "confident neutral stance", "seed": 1006},\n    {"name": "train_07_low_angle",\n     "framing": "medium shot from a low angle looking up",\n     "lighting": "harsh midday sun with strong shadows",\n     "expression": "challenging half-smile", "seed": 1007},\n    {"name": "train_08_high_angle",\n     "framing": "close-up from slightly above, looking up at the camera",\n     "lighting": "soft light from above",\n     "expression": "curious, eyebrows slightly raised", "seed": 1008},\n    {"name": "train_09_cafe_interior",\n     "framing": "medium shot seated at a table",\n     "lighting": "warm tungsten interior light, shallow depth of field",\n     "expression": "thoughtful, looking away", "seed": 1009},\n    {"name": "train_10_beach_daylight",\n     "framing": "medium shot on a beach, sea behind",\n     "lighting": "bright direct sun, high contrast",\n     "expression": "squinting slightly into the sun, easy smile", "seed": 1010},\n    {"name": "train_11_evening_portrait",\n     "framing": "close-up portrait, head turned fifteen degrees",\n     "lighting": "blue hour ambient with warm practical light",\n     "expression": "calm, direct gaze", "seed": 1011},\n    {"name": "train_12_studio_neutral",\n     "framing": "head and shoulders against a plain mid-grey backdrop",\n     "lighting": "even studio softbox lighting",\n     "expression": "neutral catalog expression", "seed": 1012},\n    {"name": "train_13_over_shoulder",\n     "framing": "medium shot over one shoulder looking back at the camera",\n     "lighting": "late sun raking across the frame",\n     "expression": "slight smirk", "seed": 1013},\n    {"name": "train_14_hat_optional",\n     "framing": "medium shot, hands in pockets, shoulders relaxed",\n     "lighting": "diffused city light",\n     "expression": "warm half-smile", "seed": 1014},\n    {"name": "train_15_tight_face",\n     "framing": "very tight close-up on the eyes and jaw",\n     "lighting": "dramatic side light, deep shadow on one side",\n     "expression": "intense direct gaze", "seed": 1015},\n]\n\n\ndef dataset_prompt(entry: Dict[str, object]) -> str:\n    """The full prompt for one training photograph."""\n    return check_prompt(\n        f"{SUBJECT}, {entry[\'framing\']}, {entry[\'lighting\']}, "\n        f"{entry[\'expression\']}, no hands near the face, "\n        "plain everyday clothing, simple uncluttered background, "\n        f"{PHOTO_REALISM}"\n    )\n\n\n# --------------------------------------------------------------------------- #\n# Carousel — four finished slides\n# --------------------------------------------------------------------------- #\n#: The mandatory prompt rules, per the brief:\n#:   * `medium full shot` and `full body` framing, so a car or a railing cannot\n#:     crop him in half;\n#:   * `candid 24mm iPhone 16 Pro photo`, `natural sunlight`, `skin pores` on\n#:     every slide;\n#:   * no hands near the face.\nCAROUSEL: List[Dict[str, object]] = [\n    # Slide 01 is the master portrait itself, re-rendered through the LoRA.\n    # It keeps this exact filename and framing because it is also the source\n    # image SadTalker animates in process 2: a medium full shot on a yacht makes\n    # a poor talking head, and a portrait makes the right one. Keeping the two\n    # identical is what makes either version a valid avatar source.\n    {"file": "01_luca_master.png",\n     "seed": 42, "size": (1024, 1024),\n     "scene": "close-up portrait facing the camera, plain white linen shirt, "\n              "blurred Mediterranean harbour behind him",\n     "expression": "relaxed neutral expression, soft window light"},\n    {"file": "02_luca_yacht.png",\n     "seed": 43, "size": (832, 1024),\n     "scene": "full body shot standing barefoot at the bow of the same yacht, "\n              "Mediterranean sea and coastline behind, one hand resting on the "\n              "railing at chest height and the other holding sunglasses at his "\n              "side, both hands clearly visible with five natural fingers",\n     "expression": "looking off toward the horizon, relaxed"},\n    {"file": "03_luca_porsche.png",\n     "seed": 44, "size": (832, 1024),\n     "scene": "medium full shot leaning against the front fender of a parked "\n              "white Porsche 911 GT3 RS on a cliffside road above the Amalfi "\n              "coast, whole car door and both legs in frame, no part of him "\n              "clipped by the car, arms folded loosely across his chest with "\n              "both hands visible and five natural fingers",\n     "expression": "sunglasses pushed up into his hair, easy confidence"},\n    {"file": "04_luca_party.png",\n     "seed": 45, "size": (832, 1024),\n     "scene": "medium full shot at an exclusive Ibiza rooftop party at night, "\n              "warm string lights and blurred crowd behind, wearing an open "\n              "black silk shirt, holding a whiskey glass at chest height in one "\n              "hand, both hands clearly visible with five natural fingers",\n     "expression": "relaxed half-smile, direct on-camera flash"},\n]\n\n\ndef carousel_prompt(entry: Dict[str, object]) -> str:\n    """The full prompt for one carousel image."""\n    return check_prompt(\n        f"{SUBJECT}, {entry[\'scene\']}, {entry[\'expression\']}, "\n        f"no hands near the face, {PHOTO_REALISM}"\n    )\n'

#: scripts/luca_v2/luca_lora.py · sha256:79de85eb7131075b
LUCA_LORA_PY = '"""\nFast SDXL LoRA training on a 15-image identity dataset.\n\nDeliberately small and hand-rolled rather than a wrapper around `train_text_to_image_lora_sdxl.py`:\nthat script assumes a dataset directory, an accelerate launcher and a full\nvalidation pass, none of which apply to 15 images on a 14.5 GB T4.\n\nWhat this is\n------------\nA peft adapter (r=16, lora_alpha=16) on the UNet\'s attention projections,\ntrained in float16 with gradient checkpointing at 768px. The text encoders are\nfrozen and pre-encoded once per image, so the only forward pass per step is the\nUNet. At batch 1 and 400 steps that is minutes, not hours.\n\nDesign notes that matter\n------------------------\n* ``latents are cached``: the VAE is run once per image up front and then\n  released, so it never competes with the UNet for VRAM during training.\n* ``text embeds are cached``: SDXL\'s two encoders are 2.5 GB and would otherwise\n  sit resident for a stage that never updates them.\n* ``the attention mask is omitted``, matching diffusers\' own ``encode_prompt``.\n  Passing one is what triggers the classic "all-zero embeddings for one batch"\n  bug in every published SDXL LoRA trainer.\n* ``no PEFT wrapper on the whole UNet``: only the adapter tensors get optimiser\n  state, which is what keeps AdamW\'s footprint at tens of MB instead of GBs.\n"""\n\nfrom __future__ import annotations\n\nimport math\nimport time\n\nimport torch.nn as torch_nn\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom luca_common import log, timed\n\n#: Attention projections every SDXL LoRA targets. These are in the\n#: transformer blocks only — the resnet convs carry little identity information\n#: and quadrupling the adapter size for them is a bad trade on a T4.\nLORA_TARGETS = ["to_q", "to_k", "to_v", "to_out.0"]\n\n\nclass _UnwrapDownBlock(torch_nn.Module):\n    """\n    Make an encoder down block return only its hidden states.\n\n    diffusers\' ``DownBlock2D.forward`` returns ``(hidden_states, output_states)``,\n    and ``Encoder.forward`` assigns that tuple straight to ``sample``:\n\n        for down_block in self.down_blocks:\n            sample = down_block(sample)\n\n    so the next block receives a tuple and ``group_norm`` raises\n    "\'tuple\' object has no attribute \'dim\'". This only bites the *encode* path —\n    a pipeline that generates never calls it, which is why the previous pipeline\n    on this repo never hit it, and why a LoRA trainer that caches latents hits it\n    immediately. Unwrapping here is version-agnostic: a block that returns a\n    plain tensor passes through untouched.\n    """\n\n    def __init__(self, inner):\n        super().__init__()\n        self.inner = inner\n\n    def forward(self, hidden_states, *args, **kwargs):\n        out = self.inner(hidden_states, *args, **kwargs)\n        return out[0] if isinstance(out, tuple) else out\n\n\ndef patch_vae_encoder(vae) -> int:\n    """Wrap every encoder down block; returns how many were wrapped."""\n    count = 0\n    for index, block in enumerate(list(vae.encoder.down_blocks)):\n        if not isinstance(block, _UnwrapDownBlock):\n            vae.encoder.down_blocks[index] = _UnwrapDownBlock(block)\n            count += 1\n    if count:\n        log(f"encoder down blocks unwrapped for the encode path ({count})")\n    return count\n\n\ndef build_adapter(unet, rank: int = 16, alpha: int = 16):\n    """Attach a peft LoRA to the UNet\'s attention projections."""\n    from peft import LoraConfig, get_peft_model\n\n    config = LoraConfig(\n        r=rank,\n        lora_alpha=alpha,\n        init_lora_weights="gaussian",     # non-zero B: the adapter moves from step 0\n        target_modules=LORA_TARGETS,\n    )\n    model = get_peft_model(unet, config)\n    trainable = [p for p in model.parameters() if p.requires_grad]\n    total = sum(p.numel() for p in trainable)\n    log(f"LoRA attached: r={rank} alpha={alpha} · {total:,} trainable "\n        f"parameters · targets={LORA_TARGETS}")\n    return model, trainable\n\n\ndef save_adapter(model, path: Path) -> Path:\n    """\n    Write ONE safetensors file that diffusers can load with\n    ``load_lora_weights()``.\n\n    peft emits keys like\n    ``base_model.model.down_blocks.1....to_q.lora_A.weight``; diffusers expects\n    ``unet.down_blocks.1....to_q.lora_A.default.weight``. The rename is done\n    explicitly rather than through ``convert_state_dict_to_peft``, which cannot\n    infer the direction from a peft-shaped dict.\n    """\n    import torch\n    from peft.utils import get_peft_model_state_dict\n    from safetensors.torch import save_file\n\n    state = get_peft_model_state_dict(model)\n    converted: Dict[str, Any] = {}\n    for key, value in state.items():\n        key = key.replace("base_model.model.", "")\n        key = key.replace(".lora_A.weight", ".lora_A.default.weight")\n        key = key.replace(".lora_B.weight", ".lora_B.default.weight")\n        if not key.startswith("unet."):\n            key = "unet." + key\n        # Keep the tensors in float32: the LoRA is applied to fp16 weights at\n        # inference, and storing fp16 here loses precision for no size benefit.\n        converted[key] = value.detach().to(device="cpu", dtype=torch.float32)\n\n    path.parent.mkdir(parents=True, exist_ok=True)\n    save_file(converted, str(path))\n    log(f"wrote {path.name} ({path.stat().st_size / 1e6:.1f} MB, "\n        f"{len(converted)} tensors)")\n    return path\n\n\ndef _ceil_to_8(value: int) -> int:\n    return int(math.ceil(value / 8.0) * 8)\n\n\ndef train(\n    *,\n    image_paths: List[Path],\n    prompts: List[str],\n    base_model: str,\n    lora_path: Path,\n    device: str = "cuda:0",\n    resolution: int = 768,\n    rank: int = 16,\n    alpha: int = 16,\n    learning_rate: float = 1e-4,\n    max_train_steps: int = 400,\n    batch_size: int = 1,\n    seed: int = 1234,\n    tag: str = "img",\n) -> Dict[str, Any]:\n    """\n    Train the identity LoRA and return a summary for luca_metrics.json.\n\n    Raises on any real failure — the caller treats a half-trained adapter as no\n    adapter at all, because a carousel generated from one is worse than a clear\n    error.\n    """\n    import torch\n    import torch.nn.functional as F\n    from diffusers import AutoencoderKL, DDPMScheduler, UNet2DConditionModel\n    from transformers import CLIPTextModel, CLIPTextModelWithProjection, CLIPTokenizer\n\n    if len(image_paths) != len(prompts):\n        raise ValueError("every training image needs exactly one caption")\n    if not image_paths:\n        raise ValueError("no training images")\n\n    timings: Dict[str, float] = {}\n    started = time.perf_counter()\n    torch.manual_seed(seed)\n\n    # ---- tokeniser + encoders -------------------------------------------- #\n    with timed("lora_load_text_encoders", timings, tag):\n        tokenizer = CLIPTokenizer.from_pretrained(\n            base_model, subfolder="tokenizer")\n        tokenizer_2 = CLIPTokenizer.from_pretrained(\n            base_model, subfolder="tokenizer_2")\n        text_encoder = CLIPTextModel.from_pretrained(\n            base_model, subfolder="text_encoder", torch_dtype=torch.float16)\n        text_encoder_2 = CLIPTextModelWithProjection.from_pretrained(\n            base_model, subfolder="text_encoder_2", torch_dtype=torch.float16)\n        for encoder in (text_encoder, text_encoder_2):\n            encoder.to(device, dtype=torch.float16).requires_grad_(False).eval()\n\n    # ---- pre-encode prompt + pooled embeddings ---------------------------- #\n    with timed("lora_encode_prompts", timings, tag):\n        prompt_embeds, pooled_embeds = [], []\n        with torch.no_grad():\n            for caption in prompts:\n                # `padding="max_length"` and no attention mask: this is exactly\n                # what diffusers\' own encode_prompt does, and omitting the mask\n                # is what avoids the all-zero-embedding bug.\n                tokens = tokenizer(\n                    caption, padding="max_length", max_length=77,\n                    truncation=True, return_tensors="pt").input_ids.to(device)\n                tokens_2 = tokenizer_2(\n                    caption, padding="max_length", max_length=77,\n                    truncation=True, return_tensors="pt").input_ids.to(device)\n\n                out_1 = text_encoder(tokens, output_hidden_states=True)\n                out_2 = text_encoder_2(tokens_2, output_hidden_states=True)\n                # SDXL concatenates the penultimate hidden states of both\n                # encoders along the channel axis: 768 + 1280 = 2048.\n                prompt_embeds.append(\n                    torch.cat([out_1.hidden_states[-2], out_2.hidden_states[-2]],\n                              dim=-1))\n                # only the final encoder\'s pooled output is used\n                pooled_embeds.append(out_2[0])\n        prompt_embeds = torch.stack(prompt_embeds).squeeze(1)   # [N, 77, 2048]\n        pooled_embeds = torch.stack(pooled_embeds).squeeze(1)   # [N, 1280]\n        log(f"encoded {len(prompts)} captions → "\n            f"{tuple(prompt_embeds.shape)} + pooled {tuple(pooled_embeds.shape)}",\n            tag=tag)\n\n    # The encoders are 2.5 GB and never updated again. Release them before the\n    # UNet and its activations need the card.\n    del text_encoder, text_encoder_2\n    torch.cuda.empty_cache()\n\n    # ---- cache latents once, then drop the VAE ---------------------------- #\n    with timed("lora_cache_latents", timings, tag):\n        from PIL import Image\n        import numpy as np\n\n        vae = AutoencoderKL.from_pretrained(\n            base_model, subfolder="vae", torch_dtype=torch.float16)\n        vae.to(device, dtype=torch.float16).requires_grad_(False).eval()\n        # encode() is the broken path on diffusers 0.42; see _UnwrapDownBlock.\n        patch_vae_encoder(vae)\n\n        height = _ceil_to_8(resolution)\n        width = _ceil_to_8(resolution)\n        latents: List[Any] = []\n        with torch.no_grad():\n            for path in image_paths:\n                with Image.open(path) as handle:\n                    image = handle.convert("RGB")\n                    # centre-crop to the training aspect, then resize: keeps the\n                    # subject centred without distorting his face\n                    side = min(image.size)\n                    left = (image.size[0] - side) // 2\n                    top = (image.size[1] - side) // 2\n                    image = image.crop((left, top, left + side, top + side))\n                    image = image.resize((width, height), Image.LANCZOS)\n                    array = np.asarray(image, dtype=np.float32) / 127.5 - 1.0\n                tensor = torch.from_numpy(array).permute(2, 0, 1)[None]\n                tensor = tensor.to(device, dtype=torch.float16)\n                latent = vae.encode(tensor).latent_dist.sample()\n                latents.append(latent * vae.config.scaling_factor)\n        del vae\n        torch.cuda.empty_cache()\n        latents = torch.cat(latents, dim=0)                    # [N, 4, H/8, W/8]\n        log(f"cached {latents.shape[0]} latents at "\n            f"{latents.shape[-1] * 8}px → {tuple(latents.shape)}", tag=tag)\n\n    # ---- UNet + adapter ---------------------------------------------------- #\n    with timed("lora_load_unet", timings, tag):\n        unet = UNet2DConditionModel.from_pretrained(\n            base_model, subfolder="unet", torch_dtype=torch.float16)\n        unet.to(device, dtype=torch.float16)\n        unet.requires_grad_(False)\n        unet.enable_gradient_checkpointing()   # trades compute for VRAM\n        unet.train()\n        model, trainable = build_adapter(unet, rank=rank, alpha=alpha)\n        # The adapter stays in float32 on purpose. Its forward folds the LoRA\n        # delta into the fp16 weights, so a fp16 *parameter* is not required —\n        # and casting the trainable tensors to fp16 is what makes AdamW\'s\n        # second-moment estimate underflow and the loss go NaN.\n        for parameter in trainable:\n            parameter.data = parameter.data.float()\n        model.to(device)\n\n    noise_scheduler = DDPMScheduler.from_pretrained(\n        base_model, subfolder="scheduler")\n    # SDXL\'s micro-conditioning: original size, crop offset, target size.\n    add_time_ids = torch.tensor(\n        [[height, width, 0, 0, height, width]], device=device,\n        dtype=torch.float16)\n\n    optimizer = torch.optim.AdamW(trainable, lr=learning_rate,\n                                  betas=(0.9, 0.999), weight_decay=1e-2,\n                                  eps=1e-8)\n\n    log(f"training: {max_train_steps} steps · batch {batch_size} · "\n        f"lr {learning_rate} · {height}px · fp16 + gradient checkpointing", tag=tag)\n\n    losses: List[float] = []\n    step_started = time.perf_counter()\n    for step in range(max_train_steps):\n        index = torch.randint(0, latents.shape[0], (batch_size,)).tolist()\n        batch_latents = latents[index].to(device, dtype=torch.float16)\n        batch_prompts = prompt_embeds[index].to(device, dtype=torch.float16)\n        batch_pooled = pooled_embeds[index].to(device, dtype=torch.float16)\n        batch_ids = add_time_ids.repeat(len(index), 1)\n\n        noise = torch.randn_like(batch_latents)\n        timesteps = torch.randint(\n            0, noise_scheduler.config.num_train_timesteps, (len(index),),\n            device=device).long()\n        noisy = noise_scheduler.add_noise(batch_latents, noise, timesteps)\n\n        prediction = model(\n            noisy, timesteps, encoder_hidden_states=batch_prompts,\n            added_cond_kwargs={"text_embeds": batch_pooled,\n                               "time_ids": batch_ids},\n        ).sample\n\n        # v-prediction models need a different target; SDXL/RealVisXL is\n        # epsilon-prediction, but ask the scheduler rather than assume.\n        if getattr(noise_scheduler.config, "prediction_type", "epsilon") == "v_prediction":\n            target = noise_scheduler.get_velocity(batch_latents, noise, timesteps)\n        else:\n            target = noise\n\n        loss = F.mse_loss(prediction.float(), target.float(),\n                          reduction="mean")\n        loss.backward()\n        torch.nn.utils.clip_grad_norm_(trainable, 1.0)\n        optimizer.step()\n        optimizer.zero_grad(set_to_none=True)\n\n        loss_value = float(loss.detach())\n        losses.append(loss_value)\n        if not math.isfinite(loss_value):\n            # fp16 master weights + AdamW can overflow on the first few steps:\n            # the loss goes NaN and every later step is garbage, but nothing\n            # raises. This is the failure mode that silently produces an adapter\n            # that changes nothing, so bail with a diagnosable message instead.\n            log(f"loss became non-finite at step {step + 1} "\n                f"({loss_value}) — fp16 overflow, restarting in float32 would be "\n                f"needed", "ERROR", tag)\n            raise RuntimeError(\n                f"LoRA training diverged at step {step + 1}: loss={loss_value}. "\n                f"Lower the learning rate or train the adapter in float32.")\n        if step % 25 == 0 or step == max_train_steps - 1:\n            elapsed = time.perf_counter() - step_started\n            rate = elapsed / (step + 1)\n            log(f"  step {step + 1}/{max_train_steps} · "\n                f"loss {losses[-1]:.4f} · {rate:.2f}s/step · "\n                f"eta {(max_train_steps - step - 1) * rate / 60:.1f} min",\n                tag=tag)\n\n    with timed("lora_save", timings, tag):\n        save_adapter(model, lora_path)\n\n    total_seconds = round(time.perf_counter() - started, 1)\n    first = sum(losses[:25]) / max(1, len(losses[:25]))\n    last = sum(losses[-25:]) / max(1, len(losses[-25:]))\n    log(f"training done in {total_seconds / 60:.1f} min · "\n        f"loss {first:.4f} → {last:.4f} · "\n        f"{\'decreasing\' if last < first else \'NOT decreasing\'}", tag=tag)\n\n    # Free everything so the inference pipeline starts from a clean card.\n    del model, unet, optimizer, latents, prompt_embeds, pooled_embeds\n    import gc\n\n    gc.collect()\n    torch.cuda.empty_cache()\n\n    return {\n        "base_model": base_model,\n        "adapter": str(lora_path.name),\n        "rank": rank,\n        "alpha": alpha,\n        "learning_rate": learning_rate,\n        "max_train_steps": max_train_steps,\n        "batch_size": batch_size,\n        "resolution": height,\n        "images": len(image_paths),\n        "precision": "float16 with gradient checkpointing",\n        "loss_first_25": round(first, 4),\n        "loss_last_25": round(last, 4),\n        "loss_decreasing": last < first,\n        "adapter_mb": round(lora_path.stat().st_size / 1e6, 2),\n        "train_seconds": total_seconds,\n        "timings_seconds": timings,\n    }\n'

#: scripts/luca_v2/generate_images.py · sha256:9a70ee428ea9e55c
GENERATE_IMAGES_PY = '"""\nLuca Moretti — Process 1 of 2: character LoRA on cuda:0.\n\nOne run, three stages, in this order and for these reasons:\n\n  1. DATASET   A clean 27-year-old master portrait, then 15 varied photographs of\n               the same person via InstantID. InstantID is a *reference* model:\n               it needs an existing face to anchor to, which is why the master\n               comes first and why it cannot be the thing that generates the\n               final carousel.\n\n  2. TRAINING  Once the 15 images exist the identity can live in the weights\n               instead of in a per-image adapter. InstantID is unloaded\n               completely — both its ControlNet and its 1.7 GB projection\n               network — before a single training step, because on a 14.5 GB T4\n               the training UNet, its activations and a resident ControlNet do\n               not coexist.\n\n  3. CAROUSEL  The four finals are generated by RealVisXL + the trained LoRA and\n               *nothing else*. No InstantID, no ControlNet, no reference image.\n               That is the entire point of training: the identity is in the\n               weights, so the pipeline is plain SDXL and every prompt is free to\n               put him anywhere.\n\nThe third stage deliberately runs even if training failed — a carousel from the\nbase model without the adapter is still a usable carousel, and it is honest\nabout what it is (``lora_used: false`` in the metrics).\n"""\n\nfrom __future__ import annotations\n\nimport gc\nimport json\nimport os\nimport sys\nimport time\nimport traceback\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nimport luca_character as character\nfrom luca_common import (BUILD_LOG, METRICS_PATH, OUTPUT_DIR, Tee, log,\n                         merge_metrics, missing_packages, pip_install, timed, ts)\nimport luca_lora\n\n# --------------------------------------------------------------------------- #\n# Configuration\n# --------------------------------------------------------------------------- #\n\nBASE_MODEL = os.environ.get("LUCA_BASE_MODEL", "SG161222/RealVisXL_V5.0")\nINSTANTID_REPO = "InstantX/InstantID"\nINSTANTID_ADAPTER = "ip-adapter.bin"\nINSTANTID_CONTROLNET = "ControlNetModel"\n\nDEVICE = "cuda:0"\nDATASET_DIR = OUTPUT_DIR / "dataset"\nLORA_FILENAME = "luca_lora.safetensors"\nMASTER_FILENAME = "01_luca_master.png"\n\n#: Everything the carousel needs. Deliberately NOT including training deps.\nIMAGE_DEPS = ["compel>=2.0.2", "einops", "onnx==1.23.2",\n              "onnxruntime-gpu==1.22.0", "opencv-python-headless"]\nTRAIN_DEPS = ["peft>=0.13", "accelerate>=1.0", "safetensors"]\nINSTANTID_DEPS = ["insightface==2.1"] + ["scikit-image", "requests", "scipy"]\n\n#: InstantID settings for the *dataset* stage only. These are not used on the\n#: final carousel — that is plain SDXL + LoRA.\nDATASET_IP_SCALE = 0.80\nDATASET_CONTROLNET_SCALE = 0.55\nDATASET_STEPS = 28\nDATASET_CFG = 4.0\nDATASET_SIZE = (832, 1024)\n\n#: Nano-banana sanity check on how much framing text the LoRA learns from.\nMASTER_PROMPT_SUFFIX = ("close-up portrait facing the camera, soft window light, "\n                        "relaxed neutral expression, plain white linen shirt, "\n                        "no hands near the face, blurred Mediterranean harbour "\n                        "behind him")\n\nTRAIN_STEPS = int(os.environ.get("LUCA_TRAIN_STEPS", "400"))\nTRAIN_RESOLUTION = int(os.environ.get("LUCA_TRAIN_RESOLUTION", "768"))\nTRAIN_LR = float(os.environ.get("LUCA_TRAIN_LR", "1e-4"))\nLORA_RANK = int(os.environ.get("LUCA_LORA_RANK", "16"))\nLORA_ALPHA = int(os.environ.get("LUCA_LORA_ALPHA", "16"))\nLORA_SCALE = float(os.environ.get("LUCA_LORA_SCALE", "0.85"))\nCAROUSEL_STEPS = int(os.environ.get("LUCA_CAROUSEL_STEPS", "30"))\nCAROUSEL_CFG = float(os.environ.get("LUCA_CAROUSEL_CFG", "4.0"))\n\n\n# --------------------------------------------------------------------------- #\n# Dependencies\n# --------------------------------------------------------------------------- #\n\n\ndef ensure_deps(timings: Dict[str, float]) -> None:\n    """\n    Install what is missing, in the order that cannot break the runtime.\n\n    insightface is installed ``--no-deps`` and *after* the headless opencv: its\n    wheel declares the GUI opencv, which imports libGL and is absent on Kaggle,\n    and a normal resolve would also let it downgrade numpy under torch.\n    """\n    with timed("pip_install_deps", timings):\n        missing = missing_packages(IMAGE_DEPS + TRAIN_DEPS)\n        if missing:\n            plain = [m for m in missing if not m.startswith("insightface")]\n            if plain and not pip_install(plain):\n                raise RuntimeError("dependency install failed — see above")\n        if missing_packages(INSTANTID_DEPS):\n            if not pip_install(["insightface==2.1"], no_deps=True):\n                raise RuntimeError("insightface install failed — see above")\n            pip_install([m for m in INSTANTID_DEPS if not m.startswith("insightface")])\n            pip_install(["--force-reinstall", "--no-deps", "opencv-python-headless"])\n        for module in ("cv2", "insightface", "compel", "diffusers", "peft"):\n            __import__(module)\n        log("image dependencies import cleanly")\n\n\n# --------------------------------------------------------------------------- #\n# Stage 1 — dataset\n# --------------------------------------------------------------------------- #\n\n\ndef face_providers() -> List[str]:\n    """CUDA when onnxruntime actually exposes it, else CPU."""\n    try:\n        import onnxruntime as ort\n\n        available = list(ort.get_available_providers())\n    except Exception as exc:\n        log(f"onnxruntime unavailable: {exc}", "WARN")\n        return ["CPUExecutionProvider"]\n    wanted = [p for p in available if "CUDA" in p][:1] + ["CPUExecutionProvider"]\n    log(f"onnxruntime providers available={available} → using={wanted}")\n    return wanted\n\n\ndef load_face_app(root: Path):\n    """antelopev2 — the 512-d face encoder InstantID is trained against."""\n    import shutil\n\n    from huggingface_hub import hf_hub_download\n\n    files = ("scrfd_10g_bnkps.onnx", "glintr100.onnx", "1k3d68.onnx",\n             "2d106det.onnx", "genderage.onnx")\n    model_dir = root / "models" / "antelopev2"\n    if not all((model_dir / name).is_file() for name in files):\n        model_dir.mkdir(parents=True, exist_ok=True)\n        for name in files:\n            local = hf_hub_download("DIAMONIK7777/antelopev2", name)\n            shutil.copy2(local, model_dir / name)\n        log(f"antelopev2 staged ({model_dir})")\n\n    from insightface.app import FaceAnalysis\n\n    app = FaceAnalysis(name="antelopev2", root=str(root),\n                       providers=face_providers())\n    app.prepare(ctx_id=0, det_size=(640, 640))\n    return app\n\n\n#: Detection scales, largest first. antelopev2\'s detector is the SCRFD-10G that\n#: InstantID itself uses; it is trained on faces occupying a decent share of the\n#: frame, and at det_size 640 a medium or full body shot leaves far too few\n#: pixels on the face to find. Run 45980957305 lost 12 of 15 dataset images this\n#: way — the same detector that found the close-up master missed everything\n#: wider than a head-and-shoulders crop.\nDET_SIZES = ((640, 640), (1024, 1024))\n\n\ndef detect_face(app, image_rgb):\n    """\n    The largest male face, or the largest face if none scores male.\n\n    Detection escalates rather than giving up: a smaller det_size is the cheaper\n    attempt, a larger one costs ~2.5x the compute but resolves faces that are\n    small in frame. Giving up after one scale is what silently shrank the\n    training set to three images.\n    """\n    import cv2\n    import numpy as np\n\n    array = image_rgb if isinstance(image_rgb, np.ndarray) else np.asarray(image_rgb)\n    bgr = cv2.cvtColor(array, cv2.COLOR_RGB2BGR)\n\n    faces = []\n    used = None\n    for det_size in DET_SIZES:\n        try:\n            app.prepare(ctx_id=0, det_size=det_size)\n        except Exception:\n            pass\n        faces = app.get(bgr)\n        used = det_size\n        if faces:\n            break\n\n    # restore the default so the next call does not inherit the widened scale\n    if used != DET_SIZES[0]:\n        try:\n            app.prepare(ctx_id=0, det_size=DET_SIZES[0])\n        except Exception:\n            pass\n\n    if not faces:\n        return None, 0\n    males = [f for f in faces if getattr(f, "sex", None) == "M"] or faces\n    best = max(males, key=lambda f: float((f.bbox[2] - f.bbox[0]) *\n                                          (f.bbox[3] - f.bbox[1])))\n    return best, len(faces)\n\n\ndef load_instantid(timings: Dict[str, float]):\n    """SDXL + InstantID as a community pipeline, for the dataset stage only."""\n    import torch\n    from diffusers.models import ControlNetModel\n\n    from fetch_instantid import ensure_pipeline\n\n    sys.path.insert(0, str(ensure_pipeline().parent))\n    from instantid_pipeline import StableDiffusionXLInstantIDPipeline, draw_kps\n\n    with timed("load_instantid", timings):\n        controlnet = ControlNetModel.from_pretrained(\n            INSTANTID_REPO, subfolder=INSTANTID_CONTROLNET,\n            torch_dtype=torch.float16)\n        pipe = StableDiffusionXLInstantIDPipeline.from_pretrained(\n            BASE_MODEL, controlnet=controlnet, torch_dtype=torch.float16,\n            variant="fp16", use_safetensors=True)\n        from huggingface_hub import hf_hub_download\n\n        pipe.load_ip_adapter_instantid(hf_hub_download(INSTANTID_REPO,\n                                                       INSTANTID_ADAPTER))\n\n        if hasattr(pipe.vae, "enable_slicing"):\n            pipe.vae.enable_slicing()\n        pipe.to(DEVICE)\n\n        # image_proj_model is created by load_ip_adapter_instantid(), after\n        # __init__, so it is not in pipe.components and pipe.to() never touches\n        # it. Left alone it stays on CPU and the first identity call dies on a\n        # device mismatch.\n        projector = getattr(pipe, "image_proj_model", None)\n        if projector is not None:\n            projector.to(DEVICE, dtype=pipe.unet.dtype)\n        try:\n            pipe.set_progress_bar_config(disable=True)\n        except Exception:\n            pass\n        log(f"InstantID ready on {DEVICE} · vae slicing on · "\n            f"projector on {DEVICE}")\n    return pipe, draw_kps\n\n\ndef build_compel(pipe):\n    from compel import CompelForSDXL\n\n    return CompelForSDXL(pipe)\n\n\ndef encode(compel, prompt: str):\n    """The four SDXL tensors, from compel (no 77-token truncation)."""\n    conditioning = compel(prompt, negative_prompt=character.NEGATIVE_PROMPT)\n    return {\n        "prompt_embeds": conditioning.embeds,\n        "pooled_prompt_embeds": conditioning.pooled_embeds,\n        "negative_prompt_embeds": conditioning.negative_embeds,\n        "negative_pooled_prompt_embeds": conditioning.negative_pooled_embeds,\n    }\n\n\ndef set_scheduler(pipe) -> None:\n    from diffusers import DPMSolverMultistepScheduler\n\n    pipe.scheduler = DPMSolverMultistepScheduler.from_config(\n        pipe.scheduler.config, use_karras_sigmas=True,\n        algorithm_type="dpmsolver++", solver_order=2)\n\n\ndef build_master(timings: Dict[str, float]) -> Dict[str, Any]:\n    """\n    Stage 1a: the one portrait that defines him, with no reference at all.\n\n    This has to come first and has to be plain SDXL: InstantID is a *reference*\n    model, so it cannot be the thing that invents the face it anchors to.\n    """\n    import torch\n    from diffusers import StableDiffusionXLPipeline\n\n    summary: Dict[str, Any] = {"file": MASTER_FILENAME}\n    DATASET_DIR.mkdir(parents=True, exist_ok=True)\n\n    with timed("build_master", timings):\n        pipe = StableDiffusionXLPipeline.from_pretrained(\n            BASE_MODEL, torch_dtype=torch.float16, variant="fp16",\n            use_safetensors=True).to(DEVICE)\n        if hasattr(pipe.vae, "enable_slicing"):\n            pipe.vae.enable_slicing()\n        set_scheduler(pipe)\n        compel = build_compel(pipe)\n\n        master_prompt = character.check_prompt(\n            f"{character.SUBJECT}, {MASTER_PROMPT_SUFFIX}")\n        image = pipe(\n            **encode(compel, master_prompt),\n            width=1024, height=1024, num_inference_steps=30, guidance_scale=3.8,\n            generator=torch.Generator(device=DEVICE).manual_seed(42),\n        ).images[0]\n        master_path = OUTPUT_DIR / MASTER_FILENAME\n        image.save(master_path, format="PNG", optimize=True)\n        log(f"master portrait written ({master_path.stat().st_size / 1024:.0f} KB)")\n        summary["prompt"] = master_prompt\n        summary["bytes"] = master_path.stat().st_size\n\n    # Free the plain pipeline before InstantID allocates its ControlNet.\n    del pipe, compel\n    gc.collect()\n    torch.cuda.empty_cache()\n    return summary\n\n\ndef build_dataset(timings: Dict[str, float], master_path: Path) -> Dict[str, Any]:\n    """\n    Stage 1b: 15 varied photographs of the *same* person, anchored by InstantID.\n\n    Variety is what the LoRA learns from. Fifteen close-ups would teach it one\n    crop; fifteen framings, lightings and expressions teach it the face.\n    """\n    import torch\n\n    summary: Dict[str, Any] = {\n        "images": 0,\n        "files": [],\n        "unverified": [],\n        "method": "master from RealVisXL, 15 variants anchored by InstantID",\n        "instantid_scales": {"ip_adapter": DATASET_IP_SCALE,\n                             "controlnet": DATASET_CONTROLNET_SCALE},\n    }\n\n    with timed("build_dataset", timings):\n        root = Path(os.environ.get("FACE_MODEL_ROOT", "/kaggle/working/face_models"))\n        app = load_face_app(root)\n        # NB: `__import__("PIL.Image").Image` is the *class*, not the module —\n        # Pillow sets `PIL.Image.Image` as an attribute of itself. Import the\n        # module explicitly. (Run 45980036759 died on exactly this.)\n        from PIL import Image as PilImage\n\n        master = PilImage.open(master_path)\n        master_face, found = detect_face(app, master)\n        if master_face is None:\n            raise RuntimeError("no face detected in the master portrait")\n        log(f"master identity locked: {found} face(s), "\n            f"bbox={[int(v) for v in master_face.bbox]}")\n        summary["master_face"] = {"detected": found,\n                                  "bbox": [int(v) for v in master_face.bbox],\n                                  "det_size": [int(v) for v in master_face.bbox[2:]]}\n\n        pipe, draw_kps = load_instantid(timings)\n        compel = build_compel(pipe)\n        face_emb = master_face.normed_embedding\n        face_kps = draw_kps(master, master_face.kps)\n        pipe.set_ip_adapter_scale(DATASET_IP_SCALE)\n\n        for index, entry in enumerate(character.DATASET, start=1):\n            prompt = character.dataset_prompt(entry)\n            path = DATASET_DIR / f"{entry[\'name\']}.png"\n            image = pipe(\n                **encode(compel, prompt),\n                image_embeds=face_emb, image=face_kps,\n                width=DATASET_SIZE[0], height=DATASET_SIZE[1],\n                num_inference_steps=DATASET_STEPS, guidance_scale=DATASET_CFG,\n                controlnet_conditioning_scale=DATASET_CONTROLNET_SCALE,\n                generator=torch.Generator(device=DEVICE).manual_seed(int(entry["seed"])),\n            ).images[0]\n            image.save(path, format="PNG", optimize=True)\n\n            # The detector is a *quality signal on the finished image*, not a\n            # filter on the pipeline. InstantID has already anchored the face, so\n            # a detection miss means the framing is wide, not that the image is\n            # unusable — and deleting it is how the training set collapsed.\n            # Keep everything, and record which images verified so a genuinely\n            # faceless render is still visible in the metrics.\n            face, _ = detect_face(app, image)\n            if face is None:\n                summary["unverified"].append(path.name)\n                log(f"  [{index}/{len(character.DATASET)}] {path.name} "\n                    f"({path.stat().st_size / 1024:.0f} KB) · face not detected "\n                    f"in-frame, kept", "WARN")\n            else:\n                summary["files"].append(path.name)\n                log(f"  [{index}/{len(character.DATASET)}] {path.name} "\n                    f"({path.stat().st_size / 1024:.0f} KB)")\n\n        summary["images"] = len(summary["files"]) + len(summary["unverified"])\n        log(f"dataset complete: {summary[\'images\']} images in {DATASET_DIR} "\n            f"({len(summary[\'files\'])} face-verified, "\n            f"{len(summary[\'unverified\'])} unverified)")\n\n        # Drop the reference model here rather than in the caller: the ControlNet\n        # and the projection network are the two largest residents on the card,\n        # and training cannot coexist with them.\n        del pipe, compel, app, draw_kps\n        gc.collect()\n\n    return summary\n\n\ndef unload_instantid(timings: Dict[str, float]) -> Dict[str, Any]:\n    """\n    Give the VRAM back before training asks for it.\n\n    InstantID\'s ControlNet plus its 1.7 GB projection network are the two\n    largest residents on a 14.5 GB T4, and the training UNet with activations\n    and gradient checkpointing does not fit alongside them. Both references are\n    dropped *and* the allocator is emptied, because `del` alone leaves the blocks\n    cached and `torch.cuda.memory_allocated` keeps reporting them as used by this\n    process.\n    """\n    import torch\n\n    freed: Dict[str, Any] = {}\n    with timed("unload_instantid", timings):\n        gc.collect()\n        torch.cuda.empty_cache()\n        try:\n            free, total = torch.cuda.mem_get_info(0)\n            freed = {"free_mb": round(free / 1024 ** 2), "total_mb": round(total / 1024 ** 2)}\n            log(f"after InstantID unload: {freed[\'free_mb\']} MB free "\n                f"of {freed[\'total_mb\']} MB")\n        except Exception:\n            log("after InstantID unload (mem_get_info unavailable)")\n    return freed\n\n\n# --------------------------------------------------------------------------- #\n# Stage 3 — carousel from the LoRA alone\n# --------------------------------------------------------------------------- #\n\n\ndef build_carousel(timings: Dict[str, float], lora_path: Optional[Path]\n                   ) -> Dict[str, Any]:\n    """\n    The four finals: RealVisXL + LoRA. No InstantID, no ControlNet, no reference.\n\n    This is where the trained weights pay off — and it is easier to get right\n    than the InstantID path, because a plain SDXL pipeline has no\n    `image`/`image_embeds` contract to satisfy.\n    """\n    import torch\n    from diffusers import StableDiffusionXLPipeline\n\n    produced: Dict[str, Any] = {"files": [], "lora_used": bool(lora_path)}\n\n    with timed("load_carousel_pipe", timings):\n        pipe = StableDiffusionXLPipeline.from_pretrained(\n            BASE_MODEL, torch_dtype=torch.float16, variant="fp16",\n            use_safetensors=True).to(DEVICE)\n        if hasattr(pipe.vae, "enable_slicing"):\n            pipe.vae.enable_slicing()\n        set_scheduler(pipe)\n        compel = build_compel(pipe)\n\n        if lora_path is not None and lora_path.is_file():\n            try:\n                pipe.load_lora_weights(\n                    str(lora_path.parent), weight_name=lora_path.name,\n                    adapter_name="luca")\n                pipe.set_adapters(["luca"], [LORA_SCALE])\n                log(f"LoRA loaded from {lora_path.name} at scale {LORA_SCALE}")\n            except Exception as exc:\n                log(f"LoRA could not be applied ({type(exc).__name__}: {exc}) — "\n                    f"falling back to the un-adapted model", "ERROR")\n                produced["lora_used"] = False\n        else:\n            log("no adapter available — generating with the base model", "WARN")\n\n    for entry in character.CAROUSEL:\n        prompt = character.carousel_prompt(entry)\n        with timed(f"generate_{entry[\'file\']}", timings):\n            image = pipe(\n                **encode(compel, prompt),\n                width=int(entry["size"][0]), height=int(entry["size"][1]),\n                num_inference_steps=CAROUSEL_STEPS, guidance_scale=CAROUSEL_CFG,\n                generator=torch.Generator(device=DEVICE).manual_seed(int(entry["seed"])),\n            ).images[0]\n            path = OUTPUT_DIR / str(entry["file"])\n            image.save(path, format="PNG", optimize=True)\n            produced["files"].append(str(entry["file"]))\n            log(f"wrote {path.name} ({path.stat().st_size / 1024:.0f} KB) · "\n                f"{entry[\'size\'][0]}x{entry[\'size\'][1]} · seed {entry[\'seed\']}")\n\n    del pipe, compel\n    gc.collect()\n    torch.cuda.empty_cache()\n    return produced\n\n\n# --------------------------------------------------------------------------- #\n# Main\n# --------------------------------------------------------------------------- #\n\n\ndef main() -> int:\n    started = time.perf_counter()\n    telemetry = Tee(BUILD_LOG, sys.stdout)\n    sys.stdout = telemetry  # type: ignore[assignment]\n\n    timings: Dict[str, float] = {}\n    metrics: Dict[str, Any] = {\n        "process": "images",\n        "device": DEVICE,\n        "status": "running",\n        "started_at": ts(),\n        "pipeline": "character LoRA (dataset → train → carousel, no InstantID at inference)",\n        "base_model": BASE_MODEL,\n        "identity": {\n            "method": "SDXL LoRA on the UNet (instantid only builds the dataset)",\n            "trigger_word": character.TRIGGER,\n            "age": character.AGE,\n            "description": character.SUBJECT,\n            "lora_scale": LORA_SCALE,\n        },\n        "prohibitions_honoured": {\n            "celebrity_name_in_prompts": False,\n            "instantid_at_inference": False,\n            "pipe.to_cpu": False,\n            "inswapper_128": False,\n            "svd_xt": False,\n            "sdxl_img2img_adetailer": False,\n        },\n        "timings_seconds": timings,\n        "errors": [],\n        "artifacts": [],\n    }\n    exit_code = 0\n\n    try:\n        ensure_deps(timings)\n\n        import torch\n\n        metrics["environment"] = {\n            "python": sys.version.split()[0],\n            "torch": torch.__version__,\n            "diffusers": __import__("diffusers").__version__,\n            "peft": __import__("peft").__version__,\n            "cuda_available": torch.cuda.is_available(),\n        }\n        log(f"environment: {json.dumps(metrics[\'environment\'])}")\n        if not torch.cuda.is_available():\n            raise RuntimeError("no CUDA device — enable a Kaggle GPU accelerator")\n        torch.cuda.set_device(0)\n\n        # ---- 1. dataset ---------------------------------------------------- #\n        # Three distinct lifetimes, so three distinct scopes: the master is plain\n        # SDXL, the variants are InstantID, and by the time training starts\n        # neither pipeline is still resident.\n        metrics["master"] = build_master(timings)\n        metrics["artifacts"].append(MASTER_FILENAME)\n\n        dataset = build_dataset(timings, OUTPUT_DIR / MASTER_FILENAME)\n        metrics["dataset"] = dataset\n\n        metrics["vram_after_unload"] = unload_instantid(timings)\n\n        # ---- 2. train ------------------------------------------------------ #\n        lora_path: Optional[Path] = OUTPUT_DIR / LORA_FILENAME\n        if dataset["images"] >= 8:\n            try:\n                metrics["training"] = luca_lora.train(\n                    image_paths=[DATASET_DIR / name\n                                 for name in dataset["files"] + dataset["unverified"]],\n                    prompts=[character.dataset_prompt(entry)\n                             for entry in character.DATASET\n                             if entry["name"] in\n                             {Path(n).stem for n in\n                              dataset["files"] + dataset["unverified"]}],\n                    base_model=BASE_MODEL, lora_path=lora_path, device=DEVICE,\n                    resolution=TRAIN_RESOLUTION, rank=LORA_RANK, alpha=LORA_ALPHA,\n                    learning_rate=TRAIN_LR, max_train_steps=TRAIN_STEPS,\n                )\n                metrics["artifacts"].append(LORA_FILENAME)\n            except Exception as exc:\n                # A failed adapter is not a failed run: the carousel can be\n                # generated without it, and saying so is more useful than a\n                # stack trace with no images.\n                detail = f"{type(exc).__name__}: {exc}"\n                log(f"LoRA training failed — carousel will use the base model: "\n                    f"{detail}", "ERROR")\n                metrics["errors"].append({"stage": "train", "error": detail})\n                lora_path = None\n        else:\n            log(f"only {dataset[\'images\']} dataset images — need at least 8 to "\n                f"train, skipping", "ERROR")\n            metrics["errors"].append({"stage": "train",\n                                      "error": "insufficient dataset"})\n            lora_path = None\n\n        # ---- 3. carousel ---------------------------------------------------- #\n        carousel = build_carousel(timings, lora_path)\n        metrics["carousel"] = carousel\n        metrics["artifacts"].extend(carousel["files"])\n\n        log("image pipeline complete — LoRA identity, no face swap, "\n            "no adetailer, no CPU offload")\n\n    except Exception as exc:\n        detail = f"{type(exc).__name__}: {exc}"\n        log(f"FATAL — {detail}", "ERROR")\n        log(traceback.format_exc(), "ERROR")\n        metrics["status"] = "failed"\n        metrics["errors"].append({"stage": "fatal", "error": detail})\n        exit_code = 1\n    finally:\n        metrics["total_seconds"] = round(time.perf_counter() - started, 1)\n        metrics["finished_at"] = ts()\n        if metrics["status"] == "running":\n            metrics["status"] = "success" if not metrics["errors"] else "success_with_errors"\n        merge_metrics("images", metrics, METRICS_PATH)\n\n        log("=" * 74)\n        log(f"image pipeline status: {metrics[\'status\']} · "\n            f"{metrics[\'total_seconds\']}s")\n        for name in metrics["artifacts"]:\n            path = OUTPUT_DIR / name\n            log(f"  {\'✓\' if path.is_file() else \'✗\'} {name}"\n                + (f" ({path.stat().st_size / 1024:.0f} KB)" if path.is_file() else ""))\n        log("=" * 74)\n        sys.stdout = telemetry._stream  # type: ignore[assignment]\n        telemetry.close()\n\n    return exit_code\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'

